INSERT INTO parks (name, lat, lon, region) SELECT 'Ange Michel', 48.5530, -1.1609, 'France' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Ange Michel');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Zéphyr', 'Ange Michel', 'Steel', 'Gerstlauer', 'Gerstlauer Euro-Fighter', 100.1, 52.0, 1246.1, 3, 60, 2027, '2027', 'year', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Zéphyr' AND park = 'Ange Michel');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Zéphyr' AND c.park = 'Ange Michel' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
