-- 116: Ange Michel (Saint-Martin-de-Landelles, Normandy, France), a new park
-- (coords the park's own), with four coasters from Carter's RCDB screenshots,
-- 2026-10-31: Zéphyr (Gerstlauer Euro-Fighter 380, opening 2027), Tacot en
-- Folie (Soquet, 12 Apr 2008), Tornado (Zamperla Twister 420m, 20 Apr 2013),
-- Tourbillon (Gosetto spinning, 22 Apr 2018). Tacot en Folie was Express at
-- Fraispertuis City, which isn't a row there, so not linked. 
-- Walygator Sud-Ouest (Roquefort, France) - a different park from Walygator
-- Grand Est (Carter) - new, with Boomerang (Vekoma, 1992; came from Zygo Park,
-- not a park here), Coccinelle (Zierer Tivoli large, 1992), Mine de Thor
-- (Zamperla Zig Zag 270m -> "Zamperla Wild Mouse", 2002), Titan (Gerstlauer
-- Euro-Fighter 600, 12 Sep 2026). Titan IS Oakwood's Speed: No Limits, moved:
-- that row is closed (2025, the year it left - nobody had logged it) and the
-- two are linked, home = Titan. Safe to run twice.
UPDATE coasters SET closed = '2025', closedPrec = 'year' WHERE name = 'Speed: No Limits' AND park = 'Oakwood' AND closed IS NULL;
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Titan' AND h.park = 'Walygator Sud-Ouest' AND (c.id = h.id OR (c.name = 'Speed: No Limits' AND c.park = 'Oakwood'));
